/* Read-only reporting workspace: summary, detail and export share one server model. */
let rpFilters={type:'leads',preset:'month',office:'',owner:'',product:'',status:'',q:'',start:'',end:'',referralType:''},rpTab='summary',rpPage=1,rpContextKey='',rpCache=null,rpBusy=false,rpError='',rpExporting=false;
function rpContext(){const key=(authUser?.id||'')+'|'+activeBranch;if(key!==rpContextKey){rpContextKey=key;rpFilters={type:'leads',preset:'month',office:'',owner:'',product:'',status:'',q:'',start:'',end:'',referralType:''};try{const old=JSON.parse(sessionStorage.getItem('bpd-reports:'+key)||'null');if(old&&typeof old==='object')for(const k of Object.keys(rpFilters))if(typeof old[k]==='string')rpFilters[k]=old[k]}catch{}rpCache=null;rpTab='summary';rpPage=1;rpError='';}return key}
function rpParams(){return new URLSearchParams(Object.entries(rpFilters).filter(([,v])=>v)).toString()}
function rpKey(){return rpContext()+'|'+rpParams()+'|'+serverRevision}
async function rpLoad(force=false){if(!authUser||!activeBranch||choosingBranch||journey||view!=='Laporan')return;const key=rpKey();if(rpBusy||!force&&(rpCache?.key===key||rpError))return;rpBusy=true;rpError='';try{const d=await api('reports?'+rpParams());if(key===rpKey())rpCache={key,data:d};}catch(e){if(key===rpKey())rpError=e.message;}finally{rpBusy=false;if(view==='Laporan')renderContent();}}
function rpApply(event){event.preventDefault();const f=Object.fromEntries(new FormData(event.target));const oldType=rpFilters.type;for(const k of Object.keys(rpFilters))rpFilters[k]=String(f[k]||'');if(!rpFilters.type)rpFilters.type='leads';if(!rpFilters.preset)rpFilters.preset='month';if(oldType!==rpFilters.type){rpFilters.status='';rpFilters.referralType='';if(rpFilters.type==='performance')rpFilters.product=''}rpPage=1;rpError='';sessionStorage.setItem('bpd-reports:'+rpContextKey,JSON.stringify(rpFilters));rpCache=null;renderContent();}
function rpPreset(value){const root=document.querySelector('#rpForm');root?.querySelectorAll('[data-custom-date]').forEach(label=>{label.hidden=value!=='custom';label.querySelector('input').disabled=value!=='custom';label.querySelector('input').required=value==='custom'});}
function rpReset(){rpFilters={...rpFilters,preset:'month',office:'',owner:'',product:'',status:'',q:'',start:'',end:'',referralType:''};rpPage=1;rpCache=null;sessionStorage.setItem('bpd-reports:'+rpContextKey,JSON.stringify(rpFilters));renderContent();}
function rpMode(tab){if(!['summary','detail','definitions'].includes(tab))return;rpTab=tab;renderContent()}
function rpMove(delta){const max=Math.max(1,Math.ceil((rpCache?.data.rows.length||0)/25));rpPage=Math.max(1,Math.min(max,rpPage+delta));renderContent();document.querySelector('.rp-data-title')?.focus({preventScroll:true})}
function rpDisplay(value,type){return value==null||value===''?'—':type==='money'?rup(value):type==='date'?value:type==='number'?new Intl.NumberFormat('id-ID').format(value):String(value)}
function rpTable(d,rows=d.rows,print=false){return '<div class="rp-table-wrap"><table class="datatable rp-table"><thead><tr>'+d.columns.map(c=>'<th scope="col">'+E(c.label)+'</th>').join('')+(!print?'<th scope="col">Tindakan</th>':'')+'</tr></thead><tbody>'+rows.map((r)=>'<tr>'+d.columns.map(c=>'<td class="'+(['money','number'].includes(c.type)?'rp-numeric':'')+'">'+E(rpDisplay(r[c.key],c.type))+'</td>').join('')+(!print?'<td><button type="button" onclick="rpOpen('+d.rows.indexOf(r)+')">Detail</button></td>':'')+'</tr>').join('')+'</tbody></table></div>'}
function rpOpen(index){const d=rpCache?.data,r=d?.rows[index];if(!r)return;const routes={lead:'Lead detail',opp:'Opportunity detail',task:'Aktivitas detail',customer:'Nasabah detail',application:'Pengajuan detail'};if(r.canOpen&&routes[r.kind]){document.querySelector('#modal')?.close();return go(routes[r.kind],r.recordId||r.id)}modal('Rincian laporan','<p class="rp-note">'+(r.canOpen?'Ringkasan aktivitas CRM.':'Monitoring baca; record berada di kantor pengawasan atau merupakan agregasi.')+'</p><dl class="rp-detail">'+d.columns.map(c=>'<div><dt>'+E(c.label)+'</dt><dd>'+E(rpDisplay(r[c.key],c.type))+'</dd></div>').join('')+'</dl>',()=>false);const form=document.querySelector('#form');form?.querySelector(':scope>.actions')?.remove();if(form)form.onsubmit=e=>e.preventDefault();}
function rpGroup(key,label){const d=rpCache?.data;if(!d)return;const rows=d.rows.filter(r=>(r[key==='referral'?'referralLabel':key]||'Belum dicatat')===label);modal('Rincian · '+E(label),'<p class="rp-note">'+rows.length+' record sesuai kelompok dan filter laporan.</p><div class="rp-group-records">'+rows.map(r=>'<button type="button" onclick="rpOpen('+d.rows.indexOf(r)+')"><strong>'+E(r.name)+'</strong><small>'+E(r.owner+' · '+r.branch)+'</small><span>'+E(r.status)+'</span></button>').join('')+'</div>',()=>false);const form=document.querySelector('#form');form?.querySelector(':scope>.actions')?.remove();if(form)form.onsubmit=e=>e.preventDefault();}
function rpGroupPanel(d,key,title){const gs=d.groups[key].filter(g=>g.label!=='Belum dicatat'),max=Math.max(1,...gs.map(g=>g.count));return '<section class="rp-panel"><h2>'+E(title)+'</h2><div class="rp-bars">'+(gs.map(g=>'<button onclick="rpGroup('+E(JSON.stringify(key))+','+E(JSON.stringify(g.label))+')"><span>'+E(g.label)+'</span><strong>'+g.count+(g.value?' · '+E(rup(g.value)):'')+'</strong><i aria-hidden="true" style="--bar:'+(g.count/max*100)+'%"></i></button>').join('')||'<p class="rp-empty">Belum ada data pada kelompok ini.</p>')+'</div><p class="rp-chart-note">Panjang bar menunjukkan jumlah record. Nominal pada label adalah nilai indikatif, bukan pendapatan.</p></section>'}
async function rpExport(){if(rpExporting||rpError||!rpCache?.data||rpCache.key!==rpKey())return;const key=rpKey();rpExporting=true;renderContent();try{const r=await fetch(API_ORIGIN+'/api/reports/export?'+rpParams()+'&revision='+encodeURIComponent(rpCache.data.revision),{headers:{Authorization:'Bearer '+currentToken(),'X-BPD-Branch':activeBranch}});if(!r.ok){let error;try{error=await r.json()}catch{}throw Error(error?.error||'Ekspor gagal. Coba lagi.')}const blob=await r.blob();if(key!==rpKey())throw Error('Konteks laporan berubah. Jalankan ekspor kembali.');const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='BPD_Bali_'+rpFilters.type+'_'+(rpCache.data.range.start||'semua')+'.xlsx';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Excel berisi Parameter, Ringkasan, dan Data berhasil diunduh.');}catch(e){toast(e.message)}finally{rpExporting=false;if(view==='Laporan')renderContent()}}
function rpPrint(){if(rpError||!rpCache?.data||rpCache.key!==rpKey())return;window.print()}
function rpSelect(name,label,values,value,extra=''){return '<label>'+E(label)+'<select name="'+name+'" '+extra+'>'+values.map(([v,t])=>'<option value="'+E(v)+'" '+(v===value?'selected':'')+'>'+E(t)+'</option>').join('')+'</select></label>'}
function rpScreen(){rpContext();const d=rpCache?.key===rpKey()?rpCache.data:null,catalog=d?.catalog||[{id:rpFilters.type,name:'Memuat katalog…'}];let html='<section class="rp-workspace"><div class="intro"><div><h1>Laporan</h1><p>Analisis operasional dan bisnis yang dapat ditelusuri ke data CRM.</p></div><div class="actions rp-export-actions"><button onclick="rpLoad(true)" '+(rpBusy?'disabled':'')+'>Perbarui</button><button class="primary" onclick="rpExport()" '+(!d||rpError||rpExporting?'disabled':'')+'>'+(rpExporting?'Menyiapkan…':'Unduh Excel')+'</button><button onclick="rpPrint()" '+(!d||rpError?'disabled':'')+'>Cetak / PDF</button></div></div>';
 const options=d?.options||{offices:[],owners:[],products:[],statuses:[]};
 const extraCount=['office','owner','product','status','q','referralType'].filter(k=>rpFilters[k]).length;
 const advanced=(options.offices.length>1?rpSelect('office','Kantor',[['','Seluruh kantor dalam akses'],...options.offices.map(o=>[o.name,o.name])],rpFilters.office):'')+(authUser?.role!=='AO'?rpSelect('owner','AO',[['','Semua AO dalam akses'],...options.owners.map(m=>[m.id,m.name+(m.active===false?' (nonaktif)':'')])],rpFilters.owner):'')+(rpFilters.type!=='performance'?rpSelect('product','Produk',[['','Semua produk'],...options.products.map(p=>[p,p])],rpFilters.product):'')+(rpFilters.type==='referrals'?rpSelect('referralType','Jenis referral',[['','Semua jenis'],['Internal','Internal'],['Eksternal','Eksternal'],['Belum ditetapkan','Belum ditetapkan']],rpFilters.referralType):'')+rpSelect('status','Status',[['','Semua status'],...options.statuses.map(s=>[s,s])],rpFilters.status)+'<label class="rp-query">Pencarian<input name="q" value="'+E(rpFilters.q)+'" placeholder="Nama, ID, AO, atau pemberi referral"></label>';
 html+='<form id="rpForm" class="rp-controls" onsubmit="rpApply(event)">'+rpSelect('type','Jenis laporan',catalog.map(r=>[r.id,r.name]),rpFilters.type)+rpSelect('preset','Periode',[['today','Hari ini'],['week','Minggu ini'],['month','Bulan ini'],['custom','Rentang tanggal'],['all','Semua tanggal']],rpFilters.preset,'onchange="rpPreset(this.value)"')+'<label data-custom-date '+(rpFilters.preset!=='custom'?'hidden':'')+'>Mulai<input type="date" name="start" value="'+E(rpFilters.start)+'" '+(rpFilters.preset!=='custom'?'disabled':'required')+'></label><label data-custom-date '+(rpFilters.preset!=='custom'?'hidden':'')+'>Sampai<input type="date" name="end" value="'+E(rpFilters.end)+'" '+(rpFilters.preset!=='custom'?'disabled':'required')+'></label><details class="rp-extra"><summary>Filter lanjutan'+(extraCount?' ('+extraCount+')':'')+'</summary><div class="rp-extra-fields">'+advanced+'</div></details><div class="rp-filter-actions"><button type="submit" class="primary">Terapkan</button><button type="button" onclick="rpReset()">Reset</button></div></form>';

 if(!d)return html+'<div class="rp-empty" role="status">'+E(rpError||'Memuat laporan…')+(rpError?'<button onclick="rpLoad(true)">Coba lagi</button>':'')+'</div></section>';
 if(rpError)html+='<div role="alert" class="rp-note">'+E(rpError)+' · Data terakhir tetap ditampilkan. Perbarui sebelum ekspor.<button onclick="rpLoad(true)">Coba lagi</button></div>';
 html+='<div class="rp-meta"><strong>'+E(d.definition.name)+'</strong><span>'+E(d.range.start?d.range.start+' s.d. '+d.range.end:'Seluruh tanggal')+' · WITA</span><span>'+d.scope.branches.length+' kantor · '+d.summary.records+' baris</span><small>Revisi '+d.revision+' · '+E(fmt(d.generatedAt))+'</small></div><div class="rp-tabs" role="group" aria-label="Tampilan laporan">'+[['summary','Ringkasan'],['detail','Rincian data'],['definitions','Definisi & batasan']].map(([v,t])=>'<button aria-pressed="'+(rpTab===v)+'" class="'+(rpTab===v?'active':'')+'" onclick="rpMode(\''+v+'\')">'+t+'</button>').join('')+'</div><p class="rp-note">Acuan periode: '+E(d.definition.basis)+'. '+E(d.definition.description)+'</p>';
 const s=d.summary;
 if(rpTab==='summary'){
  const metrics=[['Record sesuai filter',s.records],...(s.uniqueRecords!==s.records?[['Record unik',s.uniqueRecords]]:[]),...(['leads','referrals'].includes(rpFilters.type)?[['Lead handoff / konversi',s.converted],['Rasio handoff',s.conversionRate==null?'—':s.conversionRate.toLocaleString('id-ID')+'%']]:[]),...(rpFilters.type==='pipeline'?[['Opportunity aktif',s.active],['Nominal pipeline aktif',rup(s.activeValue)]]:rpFilters.type==='outcomes'?[['Nominal indikatif cohort',rup(s.value)]]:[]),...(rpFilters.type==='outcomes'?[['Won',s.won],['Lost',s.lost],['Win rate',s.winRate==null?'—':s.winRate.toLocaleString('id-ID')+'%']]:[]),...(rpFilters.type==='tasks'?[['Task selesai',s.completed],['Overdue saat ini',s.late]]:[]),...(rpFilters.type==='performance'?[['Realisasi kredit dummy',rup(d.rows.reduce((n,r)=>n+r.credit,0))],['Realisasi dana dummy',rup(d.rows.reduce((n,r)=>n+r.funding,0))]]:[])];
  html+='<div class="rp-metrics">'+metrics.sort((a,b)=>Number(String(b[1]).startsWith('Rp'))-Number(String(a[1]).startsWith('Rp'))).map(([label,v])=>'<button class="'+(String(v).startsWith('Rp')?'rp-money':'')+'" onclick="rpMode(\'detail\')"><span>'+label+'</span><strong>'+E(v)+'</strong></button>').join('')+'</div><div class="rp-grid">'+(rpFilters.type==='pipeline'?rpGroupPanel(d,'stage','Distribusi tahap sesuai filter'):rpGroupPanel(d,'status','Distribusi status'))+(rpFilters.type==='referrals'?rpGroupPanel(d,'referral','Kontribusi pemberi referral'):rpGroupPanel(d,'branch','Distribusi kantor'))+(['leads','referrals'].includes(rpFilters.type)?rpGroupPanel(d,'source','Sumber Lead'):rpGroupPanel(d,'product','Distribusi produk'))+'</div>';
 }else if(rpTab==='detail'){
  const rows=d.rows.slice((rpPage-1)*25,rpPage*25);html+='<div class="rp-data-title" tabindex="-1"><h2>Rincian data</h2><span>'+d.rows.length+' record · 25 per halaman</span></div><div class="rp-screen-table">'+rpTable(d,rows)+'</div><div class="rp-record-cards">'+(rows.map(r=>'<article><small class="rp-card-meta">'+E((r.recordId||r.id)+' · '+r.owner)+'</small><h3>'+E(r.name)+'</h3><p class="rp-card-office">'+E(r.branch)+'</p><dl>'+d.columns.filter(c=>!['id','name','owner','branch'].includes(c.key)).sort((a,b)=>{const order=['status','stage','value','realized','product','date','overdue','due'];return (order.includes(a.key)?order.indexOf(a.key):99)-(order.includes(b.key)?order.indexOf(b.key):99)}).slice(0,7).map(c=>'<div><dt>'+E(c.label)+'</dt><dd>'+E(rpDisplay(r[c.key],c.type))+'</dd></div>').join('')+'</dl><button onclick="rpOpen('+d.rows.indexOf(r)+')">Detail</button></article>').join('')||'<p class="rp-empty">Tidak ada data sesuai filter.</p>')+'</div><div class="rp-pager"><button '+(rpPage===1?'disabled':'')+' onclick="rpMove(-1)">Sebelumnya</button><span>Halaman '+rpPage+' / '+Math.max(1,Math.ceil(d.rows.length/25))+'</span><button '+(rpPage*25>=d.rows.length?'disabled':'')+' onclick="rpMove(1)">Berikutnya</button></div>';
 }else html+='<section class="rp-panel"><h2>Definisi metrik</h2><dl class="rp-definitions"><div><dt>Pipeline</dt><dd>Nominal indikatif Opportunity; basis plafon/penempatan dapat berbeda dan tidak boleh disebut pendapatan.</dd></div><div><dt>Hasil penutupan</dt><dd>Periode memakai tanggal closed yang valid. Won tanpa tanggal penutupan dikecualikan, bukan diganti tanggal masuk tahap.</dd></div><div><dt>Win rate</dt><dd>Won ÷ (Won + Lost). Cancelled tidak masuk penyebut; tanpa penutupan, rasio ditampilkan sebagai —.</dd></div><div><dt>Realisasi</dt><dd>Won + nominal positif + tanggal realisasi dalam periode + referensi konfirmasi. Seluruhnya data dummy/manual.</dd></div><div><dt>Konversi Lead</dt><dd>Lead unik yang telah memiliki Opportunity atau dikonversi menjadi Customer; dua Opportunity dari satu Lead tetap satu handoff.</dd></div><div><dt>Produktivitas</dt><dd>Task dalam cohort jadwal periode terpilih. Selesai dan dibatalkan tetap dipisah. Target vs realisasi bulanan tersedia di Monitoring / Target & Kinerja.</dd></div><div><dt>Snapshot & histori</dt><dd>Pipeline, SLA, dan status adalah kondisi saat ini dari cohort yang dipilih. Tidak merekonstruksi posisi pipeline masa lalu.</dd></div><div><dt>Ekspor</dt><dd>Excel berisi seluruh baris sesuai filter, bukan hanya halaman aktif, dengan nominal bertipe angka. Cetak/PDF memuat semua baris dan metadata.</dd></div></dl><h2>Batasan POC</h2><ul>'+d.limitations.map(t=>'<li>'+E(t)+'</li>').join('')+'</ul></section>';
 html+='<footer class="rp-warnings">'+d.warnings.map(t=>'<p>'+E(t)+'</p>').join('')+'</footer><section class="rp-print"><h1>BPD Bali · '+E(d.definition.name)+'</h1><p>Periode '+E(d.range.start?d.range.start+' s.d. '+d.range.end:'Semua tanggal')+' · Acuan: '+E(d.definition.basis)+' · WITA</p><p>Kantor: '+E(d.scope.branches.join(' | '))+' · AO: '+E(d.scope.owner||'Semua dalam akses')+' · Produk: '+E(d.scope.product||'Semua')+' · Status: '+E(d.scope.status||'Semua')+' · Pencarian: '+E(d.scope.q||'—')+'</p><p>Dibuat '+E(d.generatedAt)+' · Revisi '+d.revision+' · '+d.rows.length+' baris · Data dummy POC</p>'+rpTable(d,d.rows,true)+'</section></section>';return html;
}
reportScreen=rpScreen;
const reportContentBefore=renderContent;renderContent=function(){const r=reportContentBefore.apply(this,arguments);if(view==='Laporan'&&authUser&&!choosingBranch&&!journey)rpLoad();return r;};

document.addEventListener('pointerdown',event=>{if(!(event.target instanceof Element)||event.target.closest('[data-ui-portal]'))return;const panel=document.querySelector('.rp-extra[open]');if(panel&&!panel.contains(event.target))panel.open=false},true);
document.addEventListener('keydown',event=>{if(event.key!=='Escape')return;const panel=document.querySelector('.rp-extra[open]');if(panel){panel.open=false;panel.querySelector('summary')?.focus()}});
